{"code":"import requests

base = 'http://the-agent-company.com:8092'
webdav = base + '/remote.php/webdav'
users = [('admin','admin'), ('theagentcompany','theagentcompany'), ('admin','password'), ('theagentcompany','admin')]

working = None
for u,p in users:
    try:
        r = requests.request('PROPFIND', webdav + '/Documents', auth=(u,p), headers={'Depth':'1'})
        print((u,p), r.status_code)
        if r.status_code in (200,207):
            working = (u,p)
            break
    except Exception as e:
        print('Error for', (u,p), e)

print('Working creds:', working)
